/**
 * A line item is a snapshot of a product variant at the time it was added to the cart.
 * 
 * Since a product variant may change at any time, the ProductVariant data is copied into the field variant.
 * The relation to the Product is kept but the line item will not automatically update if the product variant changes.
 * On the cart, the line item can be updated manually. The productSlug refers to the current version of the product.
 * It can be used to link to the product. If the product has been deleted, the line item remains but refers to a
 * non-existent product and the productSlug is left empty.
 * 
 * Please also note that creating an order is impossible if the product or product variant a line item relates to has been deleted.
 */
export interface LineItem {
    addedAt: (Scalars['DateTime'] | null)
    custom: (CustomFieldsType | null)
    discountedPricePerQuantity: DiscountedLineItemPriceForQuantity[]
    distributionChannel: (Channel | null)
    distributionChannelRef: (Reference | null)
    id: Scalars['String']
    inventoryMode: (InventoryMode | null)
    key: (Scalars['String'] | null)
    lastModifiedAt: (Scalars['DateTime'] | null)
    lineItemMode: LineItemMode
    name: (Scalars['String'] | null)
    nameAllLocales: LocalizedString[]
    perMethodTaxRate: MethodTaxRate[]
    price: ProductPrice
    priceMode: LineItemPriceMode
    productId: Scalars['String']
    productKey: (Scalars['String'] | null)
    productSlug: (Scalars['String'] | null)
    productSlugAllLocales: (LocalizedString[] | null)
    productType: (ProductTypeDefinition | null)
    /** Reference to the product type of the line item, carrying the snapshot `version` captured when the line item was added. */
    productTypeRef: (VersionedReference | null)
    quantity: Scalars['Long']
    recurrenceInfo: (LineItemRecurrenceInfo | null)
    reservation: (Reservation | null)
    reservationRef: (Reference | null)
    shippingDetails: (ItemShippingDetails | null)
    state: ItemState[]
    supplyChannel: (Channel | null)
    supplyChannelRef: (Reference | null)
    taxRate: (TaxRate | null)
    taxedPrice: (TaxedItemPrice | null)
    taxedPricePortions: MethodTaxedPrice[]
    totalPrice: (Money | null)
    variant: (ProductVariant | null)
    __typename: 'LineItem'
}

